/**
 * RAG query audit — extracts tool_use/tool_result pairs from stream-json stdout.
 */

export interface RagQueryEvent {
  query: string;
  chunks_returned: number;
  top_score: number | null;
  scores: number[];
}

/**
 * Scan stream-json stdout for RAG tool_use/tool_result pairs.
 * Unmatched tool_use entries (no corresponding tool_result) are dropped silently.
 */
export function extractRagQueries(stdout: string): RagQueryEvent[] {
  const pending = new Map<string, string>(); // tool_use_id → query
  const results: RagQueryEvent[] = [];

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      continue;
    }

    if (parsed.type === "assistant") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        const b = block as Record<string, unknown>;
        if (
          b.type === "tool_use" &&
          b.name === "mcp__rag-server__rag_query" &&
          typeof b.id === "string"
        ) {
          const input = b.input as Record<string, unknown> | undefined;
          const query = typeof input?.query === "string" ? input.query : "";
          pending.set(b.id as string, query);
        }
      }
      continue;
    }

    if (parsed.type === "user") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        const b = block as Record<string, unknown>;
        if (b.type !== "tool_result" || typeof b.tool_use_id !== "string") continue;
        const query = pending.get(b.tool_use_id as string);
        if (query === undefined) continue;
        pending.delete(b.tool_use_id as string);

        const scores = parseScores(b.content);
        results.push({
          query,
          chunks_returned: scores.length,
          top_score: scores.length > 0 ? Math.max(...scores) : null,
          scores,
        });
      }
    }
  }

  return results;
}

function parseScores(content: unknown): number[] {
  if (typeof content === "string") {
    try {
      const parsed = JSON.parse(content);
      if (Array.isArray(parsed)) {
        return parsed
          .map((item: unknown) => {
            const obj = item as Record<string, unknown>;
            return typeof obj?.score === "number" ? obj.score : null;
          })
          .filter((s): s is number => s !== null);
      }
    } catch {
      return [];
    }
    return [];
  }

  if (Array.isArray(content)) {
    for (const block of content) {
      const b = block as Record<string, unknown>;
      if (b.type === "text" && typeof b.text === "string") {
        return parseScores(b.text);
      }
    }
  }

  return [];
}

