1	/**
2	 * Claude executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, materializes the
5	 * implementation repo, spawns `claude -p`, and writes ExecutorResult
6	 * to result.json at RESULT_PATH.
7	 *
8	 * Formal ABI env vars (from ExecutorInput):
9	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID
10	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_REPO_PATH
11	 *   BRIEFING_PATH, RESULT_PATH
12	 *   BUDGET_TOKENS (optional)
13	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
14	 *
15	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
16	 *   WORKSPACE_ROOT     — management repo root for task YAML reading
17	 *   TASK_BRANCH        — management repo feature branch for git commits
18	 *   GIT_AUTHOR_EMAIL   — for commit identity
19	 *   GIT_AUTHOR_NAME    — for commit identity
20	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
21	 *   MAX_TURNS          — max claude CLI turns (default: 200)
22	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
23	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
24	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
25	 *   GITNEXUS_MCP_URL   — optional GitNexus code-graph MCP server URL
26	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
27	 */
28	
29	import { spawn, execSync } from "node:child_process";
30	import {
31	  mkdirSync,
32	  appendFileSync,
33	  readFileSync,
34	  writeFileSync,
35	  existsSync,
36	  readdirSync,
37	  rmSync,
38	  copyFileSync,
39	  lstatSync,
40	} from "node:fs";
41	import { join, dirname } from "node:path";
42	import { homedir } from "node:os";
43	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
44	import type { ExecutorResult } from "@workflow/runtime-abi";
45	import { isValidResult } from "@workflow/runtime-abi";
46	import { extractTokenUsage } from "./token-usage.js";
47	import { extractRagQueries } from "./rag-audit.js";
48	import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
49	import { runRecovery, type SpawnResult } from "./recovery.js";
50	import { resolveSSHKey } from "./resolve-ssh-key.js";
51	import { redactSecrets } from "./redact-secrets.js";
52	import { buildGitEnv } from "./git-env.js";
53	
54	// ── Helpers ───────────────────────────────────────────────────────────────────
55	
56	function requireEnv(name: string): string {
57	  const val = process.env[name];
58	  if (!val) throw new Error(`Required env var ${name} is not set`);
59	  return val;
60	}
61	
62	function emit(event: Record<string, unknown>): void {
63	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
64	}
65	
66	/**
67	 * Materialize the implementation repo at taskRepoPath:
68	 *   - If path exists and origin matches URL: fetch + checkout + pull
69	 *   - Otherwise: clone fresh
70	 */
71	function materializeRepo(
72	  taskRepoUrl: string,
73	  taskRepoBranch: string,
74	  taskRepoPath: string,
75	  sshKeyPath: string | undefined,
76	): void {
77	  const env = buildGitEnv(sshKeyPath);
78	  const opts = { env, stdio: "pipe" as const };
79	
80	  if (existsSync(join(taskRepoPath, ".git"))) {
81	    let originUrl = "";
82	    try {
83	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
84	        ...opts, encoding: "utf-8",
85	      }).trim();
86	    } catch { /* no remote — fall through to clone */ }
87	
88	    if (originUrl === taskRepoUrl) {
89	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
90	      // Discard local changes from a previous session before checkout.
91	      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
92	      try {
93	        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
94	      } catch {
95	        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
96	      }
97	      try {
98	        execSync(
99	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
100	          opts,
101	        );
102	      } catch {
103	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
104	      }
105	      return;
106	    }
107	  }
108	
109	  // Clone fresh.
110	  mkdirSync(dirname(taskRepoPath), { recursive: true });
111	  if (existsSync(taskRepoPath)) {
112	    rmSync(taskRepoPath, { recursive: true, force: true });
113	  }
114	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
115	  try {
116	    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
117	  } catch {
118	    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
119	  }
120	}
121	
122	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
123	  { file: "yarn.lock",        tool: "yarn"    },
124	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
125	  { file: "bun.lockb",        tool: "bun"     },
126	  { file: "go.mod",           tool: "go"      },
127	  { file: "requirements.txt", tool: "python3" },
128	  { file: "pyproject.toml",   tool: "python3" },
129	  { file: "Cargo.toml",       tool: "cargo"   },
130	];
131	
132	function checkRequiredTools(taskRepoPath: string): string[] {
133	  const missing: string[] = [];
134	  const checked = new Set<string>();
135	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
136	    if (checked.has(tool)) continue;
137	    if (!existsSync(join(taskRepoPath, file))) continue;
138	    checked.add(tool);
139	    try {
140	      execSync(`which ${tool}`, { stdio: "pipe" });
141	    } catch {
142	      missing.push(tool);
143	    }
144	  }
145	  return missing;
146	}
147	
148	function copyWorkspaceClaude(workspaceRoot: string): void {
149	  const src = join(workspaceRoot, "CLAUDE.md");
150	  if (!existsSync(src)) return;
151	  const destDir = join(homedir(), ".claude");
152	  mkdirSync(destDir, { recursive: true });
153	  copyFileSync(src, join(destDir, "CLAUDE.md"));
154	}
155	
156	function copyDirRecursive(src: string, dest: string): void {
157	  mkdirSync(dest, { recursive: true });
158	  for (const entry of readdirSync(src)) {
159	    const srcPath = join(src, entry);
160	    const destPath = join(dest, entry);
161	    const stat = lstatSync(srcPath);
162	    if (stat.isDirectory()) {
163	      copyDirRecursive(srcPath, destPath);
164	    } else if (stat.isFile()) {
165	      copyFileSync(srcPath, destPath);
166	    }
167	  }
168	}
169	
170	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
171	  const globalSkillsDir = join(homedir(), ".claude", "skills");
172	  if (existsSync(globalSkillsDir)) {
173	    rmSync(globalSkillsDir, { recursive: true, force: true });
174	  }
175	  mkdirSync(globalSkillsDir, { recursive: true });
176	
177	  const copySkillsFrom = (sourceDir: string): void => {
178	    if (!existsSync(sourceDir)) return;
179	    let entries: string[];
180	    try { entries = readdirSync(sourceDir); } catch { return; }
181	    for (const entry of entries) {
182	      const srcPath = join(sourceDir, entry);
183	      try {
184	        const stat = lstatSync(srcPath);
185	        if (!stat.isDirectory()) continue;
186	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
187	      } catch (e) {
188	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
189	      }
190	    }
191	  };
192	
193	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
194	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
195	
196	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
197	  if (existsSync(wsSkillsDir)) {
198	    let entries: string[];
199	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
200	    for (const entry of entries) {
201	      if (entry === ".gitignore") continue;
202	      const srcPath = join(wsSkillsDir, entry);
203	      try {
204	        const stat = lstatSync(srcPath);
205	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
206	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
207	      } catch (e) {
208	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
209	      }
210	    }
211	  }
212	}
213	
214	function writeResult(resultPath: string, result: ExecutorResult): void {
215	  mkdirSync(dirname(resultPath), { recursive: true });
216	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
217	}
218	
219	// ── Main ──────────────────────────────────────────────────────────────────────
220	
221	async function main(): Promise<void> {
222	  // ── Read formal ABI env vars ────────────────────────────────────────────────
223	  let taskId: string;
224	  let featureId: string;
225	  let taskRepoUrl: string;
226	  let taskRepoBranch: string;
227	  let taskRepoPath: string;
228	  let briefingPath: string;
229	  let resultPath: string;
230	  let sshKeyPath: string | undefined;
231	  let githubToken: string;
232	
233	  try {
234	    taskId = requireEnv("TASK_ID");
235	    featureId = requireEnv("FEATURE_ID");
236	    taskRepoUrl = requireEnv("TASK_REPO_URL");
237	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
238	    taskRepoPath = requireEnv("TASK_REPO_PATH");
239	    briefingPath = requireEnv("BRIEFING_PATH");
240	    resultPath = requireEnv("RESULT_PATH");
241	    githubToken = process.env.GITHUB_TOKEN ?? "";
242	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
243	  } catch (e) {
244	    emit({ type: "executor_fatal", details: (e as Error).message });
245	    process.exit(1);
246	  }
247	
248	  const budgetTokensStr = process.env.BUDGET_TOKENS;
249	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
250	
251	  // Day-1 single-container extras.
252	  const workspaceRoot = process.env.WORKSPACE_ROOT ?? "";
253	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
254	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
255	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
256	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
257	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
258	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
259	  const mcpRagUrl = process.env.MCP_RAG_URL;
260	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
261	  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
262	  const implementationModel = process.env.IMPLEMENTATION_MODEL;
263	
264	  const runStartIso = new Date().toISOString();
265	
266	  // ── 1. Materialize implementation repo ─────────────────────────────────────
267	  try {
268	    materializeRepo(taskRepoUrl, taskRepoBranch, taskRepoPath, sshKeyPath);
269	  } catch (e) {
270	    const details = `repo materialization failed: ${String(e)}`;
271	    emit({ type: "executor_fatal", task_id: taskId, details });
272	    writeResult(resultPath, {
273	      terminal_status: "failed",
274	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
275	    });
276	    process.exit(0);
277	  }
278	
279	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
280	  const missingTools = checkRequiredTools(taskRepoPath);
281	  if (missingTools.length > 0) {
282	    const details = `missing tools: ${missingTools.join(", ")}`;
283	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
284	    writeResult(resultPath, {
285	      terminal_status: "blocked",
286	      blocked_reason: "missing_tool",
287	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
288	    });
289	    process.exit(0);
290	  }
291	
292	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
293	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
294	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
295	
296	  // ── 4. Read briefing ────────────────────────────────────────────────────────
297	  let briefingContent: string;
298	  try {
299	    briefingContent = readFileSync(briefingPath, "utf-8");
300	  } catch (e) {
301	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
302	    writeResult(resultPath, {
303	      terminal_status: "failed",
304	      blocked_reason: `briefing_read_failed: ${String(e)}`,
305	    });
306	    process.exit(0);
307	  }
308	
309	  // Append hard-stop rule for missing tools.
310	  const effectiveBriefing =
311	    briefingContent +
312	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
313	
314	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
315	  const mcpArgs: string[] = [];
316	  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
317	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
318	    if (mcpRagUrl) {
319	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
320	    }
321	    if (gitnexusMcpUrl) {
322	      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
323	    }
324	    if (figmaToken) {
325	      mcpConfig.mcpServers["figma"] = {
326	        type: "stdio",
327	        command: "npx",
328	        args: ["-y", "@figma/mcp-server"],
329	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
330	      };
331	    }
332	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
333	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
334	    mcpArgs.push("--mcp-config", mcpConfigPath);
335	  }
336	
337	  if (mcpRagUrl) {
338	    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
339	  } else {
340	    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
341	  }
342	
343	  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
344	  const claudeEnv = {
345	    ...buildGitEnv(sshKeyPath),
346	    CLAUDE_AGENT_RUNTIME: "1",
347	    RESULT_PATH: resultPath,
348	    GITHUB_TOKEN: githubToken,
349	  };
350	
351	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
352	
353	  let spawnResult: SpawnResult | undefined;
354	  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
355	  let logFlushed = false;
356	
357	  try {
358	    spawnResult = await new Promise<SpawnResult>((resolve) => {
359	      const stdoutChunks: string[] = [];
360	
361	      const child = spawn(
362	        "claude",
363	        [
364	          "-p", effectiveBriefing,
365	          "--max-turns", String(maxTurns),
366	          "--output-format", "stream-json",
367	          "--verbose",
368	          "--dangerously-skip-permissions",
369	          ...(implementationModel ? ["--model", implementationModel] : []),
370	          ...mcpArgs,
371	        ],
372	        { cwd: taskRepoPath, env: claudeEnv },
373	      );
374	
375	      child.stdout.setEncoding("utf-8");
376	      child.stderr.setEncoding("utf-8");
377	
378	      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
379	      let stdoutLineBuf = "";
380	      child.stdout.on("data", (chunk: string) => {
381	        stdoutChunks.push(chunk);
382	        process.stdout.write(chunk);
383	        if (resultWatchdog === null) {
384	          stdoutLineBuf += chunk;
385	          const lines = stdoutLineBuf.split("\n");
386	          stdoutLineBuf = lines.pop() ?? "";
387	          for (const line of lines) {
388	            if (line.includes('"type":"result"')) {
389	              resultWatchdog = setTimeout(() => {
390	                if (!child.killed) child.kill("SIGTERM");
391	              }, 30_000);
392	              break;
393	            }
394	          }
395	        }
396	      });
397	
398	      child.stderr.on("data", (chunk: string) => {
399	        process.stderr.write(chunk);
400	      });
401	
402	      child.on("error", (err: Error) => {
403	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
404	        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
405	      });
406	
407	      child.on("exit", () => {
408	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
409	        setTimeout(() => {
410	          if (!child.stdout.destroyed) child.stdout.destroy();
411	          if (!child.stderr.destroyed) child.stderr.destroy();
412	        }, 0);
413	      });
414	
415	      child.on("close", (code: number | null, signal: string | null) => {
416	        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
417	      });
418	    });
419	
420	    emit({
421	      type: "claude_exit",
422	      task_id: taskId,
423	      feature_id: featureId,
424	      exit_code: spawnResult.status,
425	      signal: spawnResult.signal ?? null,
426	    });
427	
428	    // ── 7. Token audit ────────────────────────────────────────────────────────
429	    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;
430	
431	    if (tokenUsage === undefined) {
432	      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
433	    } else {
434	      if (tokenUsage.pricingFallback) {
435	        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
436	      }
437	      emit({
438	        type: "budget_audit",
439	        task_id: taskId,
440	        feature_id: featureId,
441	        total_tokens: tokenUsage.input + tokenUsage.output,
442	        max_tokens: budgetTokens,
443	      });
444	    }
445	
446	    // ── 7a. RAG query audit
447	    if (spawnResult.stdout) {
448	      for (const rq of extractRagQueries(spawnResult.stdout)) {
449	        emit({ type: "rag_query", ...rq });
450	      }
451	    }
452	
453	    // ── 8. Check for result.json written by Claude ────────────────────────────
454	    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
455	    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
456	    // when Claude exits cleanly without writing result.json — both paths previously
457	    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
458	    // echoed via a Read of T<n>.yaml) were captured as the impl PR.
459	
460	    if (existsSync(resultPath)) {
461	      let raw: unknown;
462	      try {
463	        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
464	      } catch {
465	        raw = null;
466	      }
467	      if (isValidResult(raw)) {
468	        let claudeResult = raw as ExecutorResult;
469	        if (tokenUsage !== undefined && !claudeResult.token_usage) {
470	          claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
471	        }
472	        if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
473	          claudeResult.cost_usd = tokenUsage.cost_usd;
474	        }
475	
476	        // Refuse terminal_status: in_review without a pr_url. Catches the case
477	        // where the agent skipped pr-create after pr-self-review and exited
478	        // anyway, so the orchestrator does not advance the task to in_review
479	        // with no impl PR (or with the workspace claim PR url misclaimed as
480	        // the impl PR — see enforce-pr-url.ts for context).
481	        const enforced = enforceInReviewRequiresPrUrl(claudeResult);
482	        if (enforced.rewritten) {
483	          emit({
484	            type: "in_review_refused_no_pr_url",
485	            task_id: taskId,
486	            feature_id: featureId,
487	          });
488	        }
489	        claudeResult = enforced.result;
490	
491	        if (
492	          budgetTokens !== undefined &&
493	          tokenUsage !== undefined &&
494	          tokenUsage.input + tokenUsage.output > budgetTokens
495	        ) {
496	          writeResult(resultPath, {
497	            terminal_status: "blocked",
498	            blocked_reason: "budget_exceeded",
499	            token_usage: tokenUsage,
500	          });
501	        } else {
502	          writeResult(resultPath, claudeResult);
503	        }
504	
505	        if (logSinkEnabled && workspaceRoot && taskBranch) {
506	          flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath);
507	          logFlushed = true;
508	        }
509	
510	        // Return normally — Layer 1 recovery (finally block below) will no-op
511	        // because a valid result.json now exists.
512	        return;
513	      }
514	    }
515	
516	    // ── 9. Claude did not write result.json ──────────────────────────────────
517	    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
518	    if (
519	      budgetTokens !== undefined &&
520	      tokenUsage !== undefined &&
521	      tokenUsage.input + tokenUsage.output > budgetTokens
522	    ) {
523	      writeResult(resultPath, {
524	        terminal_status: "blocked",
525	        blocked_reason: "budget_exceeded",
526	        token_usage: tokenUsage,
527	      });
528	      if (logSinkEnabled && workspaceRoot && taskBranch) {
529	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath);
530	        logFlushed = true;
531	      }
532	      return;
533	    }
534	
535	    // No result.json produced — recovery will write one in the finally block.
536	
537	  } finally {
538	    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
539	    // Runs regardless of how the spawn ended. No-op when result.json has a
540	    // valid in_review result (Claude finished cleanly). Otherwise: commits
541	    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
542	    // writes a blocked result.json.
543	    await runRecovery({
544	      spawnResult,
545	      taskId,
546	      featureId,
547	      taskRepoBranch,
548	      taskRepoPath,
549	      taskRepoUrl,
550	      githubToken,
551	      sshKeyPath,
552	      gitAuthorEmail,
553	      gitAuthorName,
554	      resultPath,
555	      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
556	    });
557	
558	    // Flush log after recovery (best-effort, uses result.json to determine outcome).
559	    // Skip if already flushed in the success or budget-exceeded paths above.
560	    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
561	      let outcome = "unknown";
562	      try {
563	        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
564	        outcome = raw.terminal_status;
565	      } catch { /* ignore */ }
566	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath);
567	    }
568	  }
569	}
570	
571	// ── Log flush (best-effort) ───────────────────────────────────────────────────
572	
573	function flushLog(
574	  workspaceRoot: string,
575	  featureId: string,
576	  taskId: string,
577	  taskBranch: string,
578	  runStartIso: string,
579	  gitAuthorEmail: string,
580	  gitAuthorName: string,
581	  stdout: string,
582	  outcome: string,
583	  sshKeyPath: string | undefined,
584	): void {
585	  try {
586	    const safeIso = runStartIso.replace(/[:.]/g, "-");
587	    const logFilename = `${safeIso}.jsonl`;
588	    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
589	    const logPath = join(workspaceRoot, relLogPath);
590	
591	    const env = {
592	      ...process.env,
593	      GIT_AUTHOR_NAME: gitAuthorName,
594	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
595	      GIT_COMMITTER_NAME: gitAuthorName,
596	      GIT_COMMITTER_EMAIL: gitAuthorEmail,
597	      ...(sshKeyPath ? { GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` } : {}),
598	    };
599	    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };
600	
601	    // Step 1: Move to the task branch tip BEFORE writing any files.
602	    // Discard local changes first — a previous failed flush may have left a dirty tree.
603	    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, gitOpts);
604	    execSync(`git -C "${workspaceRoot}" checkout -- .`, gitOpts);
605	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
606	
607	    // Step 2: Write the log file (directory may not exist on this branch yet).
608	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
609	    mkdirSync(logsDir, { recursive: true });
610	    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
611	    if (stdout) {
612	      const safe = redactSecrets(stdout);
613	      appendFileSync(logPath, safe.endsWith("\n") ? safe : safe + "\n");
614	    }
615	    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");
616	
617	    // Step 3: Commit, sync with origin, then push.
618	    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
619	    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
620	    execSync(`git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`, gitOpts);
621	    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
622	  } catch { /* best-effort */ }
623	}
624	
625	main().catch((e) => {
626	  try {
627	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
628	  } catch { /* last resort */ }
629	  process.exit(1);
630	});
