/**
 * GitNexus query audit — extracts mcp__gitnexus__* tool_use/tool_result pairs from stream-json stdout.
 */

export interface GitNexusQueryEvent {
  tool: string;
  arguments: Record<string, unknown>;
  result_summary: string;
  result_length: number;
}

/**
 * Scan stream-json stdout for mcp__gitnexus__* tool_use/tool_result pairs.
 * Unmatched tool_use entries (no corresponding tool_result) are dropped silently.
 */
export function extractGitNexusQueries(stdout: string): GitNexusQueryEvent[] {
  const pending = new Map<string, { tool: string; arguments: Record<string, unknown> }>();
  const results: GitNexusQueryEvent[] = [];

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      continue;
    }

    if (parsed.type === "assistant") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        const b = block as Record<string, unknown>;
        if (
          b.type === "tool_use" &&
          typeof b.name === "string" &&
          b.name.startsWith("mcp__gitnexus__") &&
          typeof b.id === "string"
        ) {
          const toolName = b.name.slice("mcp__gitnexus__".length);
          const input = (b.input ?? {}) as Record<string, unknown>;
          pending.set(b.id as string, { tool: toolName, arguments: input });
        }
      }
      continue;
    }

    if (parsed.type === "user") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        const b = block as Record<string, unknown>;
        if (b.type !== "tool_result" || typeof b.tool_use_id !== "string") continue;
        const entry = pending.get(b.tool_use_id as string);
        if (entry === undefined) continue;
        pending.delete(b.tool_use_id as string);

        const { text, length } = extractResultText(b.content);
        results.push({
          tool: entry.tool,
          arguments: entry.arguments,
          result_summary: text.slice(0, 200),
          result_length: length,
        });
      }
    }
  }

  return results;
}

function extractResultText(content: unknown): { text: string; length: number } {
  if (typeof content === "string") {
    return { text: content, length: content.length };
  }

  if (Array.isArray(content)) {
    const parts: string[] = [];
    for (const block of content) {
      const b = block as Record<string, unknown>;
      if (b.type === "text" && typeof b.text === "string") {
        parts.push(b.text);
      }
    }
    const joined = parts.join("");
    return { text: joined, length: joined.length };
  }

  return { text: "", length: 0 };
}

