import { describe, it, expect } from "vitest";
import { extractGitNexusQueries } from "./gitnexus-audit.js";

function assistantToolUse(id: string, toolName: string, args: Record<string, unknown>) {
  return JSON.stringify({
    type: "assistant",
    message: {
      content: [
        { type: "tool_use", id, name: `mcp__gitnexus__${toolName}`, input: args },
      ],
    },
  });
}

function userToolResult(toolUseId: string, content: string) {
  return JSON.stringify({
    type: "user",
    message: {
      content: [{ type: "tool_result", tool_use_id: toolUseId, content }],
    },
  });
}

describe("extractGitNexusQueries", () => {
  it("returns empty array for empty stdout", () => {
    expect(extractGitNexusQueries("")).toEqual([]);
  });

  it("extracts a single query tool call", () => {
    const stdout = [
      assistantToolUse("tu_1", "query", { symbol: "extractRagQueries" }),
      userToolResult("tu_1", "Found 3 references in rag-audit.ts"),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results).toHaveLength(1);
    expect(results[0]?.tool).toBe("query");
    expect(results[0]?.arguments).toEqual({ symbol: "extractRagQueries" });
    expect(results[0]?.result_summary).toBe("Found 3 references in rag-audit.ts");
    expect(results[0]?.result_length).toBe("Found 3 references in rag-audit.ts".length);
  });

  it("extracts multiple gitnexus tool calls", () => {
    const stdout = [
      assistantToolUse("tu_1", "query", { symbol: "foo" }),
      userToolResult("tu_1", "foo defined in foo.ts"),
      assistantToolUse("tu_2", "impact", { symbol: "bar" }),
      userToolResult("tu_2", "bar affects 5 files"),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results).toHaveLength(2);
    expect(results[0]?.tool).toBe("query");
    expect(results[1]?.tool).toBe("impact");
  });

  it("drops unmatched tool_use (no result)", () => {
    const stdout = assistantToolUse("tu_orphan", "context", { symbol: "orphan" });
    expect(extractGitNexusQueries(stdout)).toHaveLength(0);
  });

  it("ignores non-gitnexus tool_use", () => {
    const stdout = [
      JSON.stringify({
        type: "assistant",
        message: { content: [{ type: "tool_use", id: "tu_x", name: "mcp__rag-server__rag_query", input: { query: "foo" } }] },
      }),
      JSON.stringify({
        type: "user",
        message: { content: [{ type: "tool_result", tool_use_id: "tu_x", content: "some rag result" }] },
      }),
    ].join("\n");
    expect(extractGitNexusQueries(stdout)).toHaveLength(0);
  });

  it("truncates result_summary to 200 chars", () => {
    const longText = "x".repeat(300);
    const stdout = [
      assistantToolUse("tu_1", "context", { symbol: "bigResult" }),
      userToolResult("tu_1", longText),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results[0]?.result_summary).toHaveLength(200);
    expect(results[0]?.result_length).toBe(300);
  });

  it("handles text-block content format", () => {
    const resultText = "symbol defined at line 42";
    const stdout = [
      assistantToolUse("tu_1", "query", { symbol: "myFunc" }),
      JSON.stringify({
        type: "user",
        message: {
          content: [{
            type: "tool_result",
            tool_use_id: "tu_1",
            content: [{ type: "text", text: resultText }],
          }],
        },
      }),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results[0]?.result_summary).toBe(resultText);
    expect(results[0]?.result_length).toBe(resultText.length);
  });

  it("extracts tool name from mcp__gitnexus__ prefix correctly", () => {
    const stdout = [
      assistantToolUse("tu_1", "detect_changes", { files: ["a.ts", "b.ts"] }),
      userToolResult("tu_1", "changes affect 2 symbols"),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results[0]?.tool).toBe("detect_changes");
    expect(results[0]?.arguments).toEqual({ files: ["a.ts", "b.ts"] });
  });

  it("handles empty result content", () => {
    const stdout = [
      assistantToolUse("tu_1", "list_repos", {}),
      userToolResult("tu_1", ""),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results[0]?.result_summary).toBe("");
    expect(results[0]?.result_length).toBe(0);
  });

  it("ignores malformed JSON lines", () => {
    const stdout = [
      "not json at all",
      assistantToolUse("tu_1", "query", { symbol: "ok" }),
      "{broken json",
      userToolResult("tu_1", "result"),
    ].join("\n");
    const results = extractGitNexusQueries(stdout);
    expect(results).toHaveLength(1);
    expect(results[0]?.tool).toBe("query");
  });
});

